use sarv_quote::{accounting::{AccountingState,MoneyUnit},core::*,core_import,core_export,domain::{DateDisplay,DisplayDigits}};
fn main(){let mut state=AccountingState::default();let setup=state.setup_core_company(NewCoreCompany{name:"شرکت مصنوعی F2-SUPPLIED".into(),fiscal_name:"سال ۱۴۰۵".into(),start_date:"2026-03-21".into(),end_date:"2027-03-20".into(),timezone:CompanyTimezone::AsiaTehran,chart:default_chart(),actor:"آزمایشگر مستقل".into()}).unwrap();let input=std::fs::read_to_string("docs/assets/accounting-m3/opening.csv").unwrap().replace("F2-core-v1",&setup.company_id);let c=core_import::opening_csv(&state,&setup.company_id,&input,"آزمایشگر مستقل","supplied-report-evidence").unwrap();let p=state.opening_preview(&c).unwrap();assert_eq!(p.total_debit.rials(),1251);assert_eq!(p.total_credit.rials(),1251);assert!(p.reconciled);assert!(p.controls.iter().all(|c|c.difference.rials()==0));state.post_opening(c).unwrap();let path=std::path::Path::new("docs/assets/accounting-m3/export");core_export::opening_csv_with_preferences(&state,&setup.company_id,MoneyUnit::Toman,DateDisplay::Jalali,DisplayDigits::Latin,&path.join("opening-supplied-human.csv")).unwrap();core_export::opening_pdf_with_preferences(&state,&setup.company_id,MoneyUnit::Toman,DateDisplay::Jalali,DisplayDigits::Latin,&path.join("opening-supplied-human.pdf")).unwrap();}
